// ya garantizó que estén las 3 (si no, PARÓ). Se prefiere la rescatada; si el nodo no
// existe (grafo viejo) el $() lanza y cae al camino de siempre · retrocompatible.
const _SLUG_POR_NODO = {
  'Lente · brand-strategist': 'brand-strategist',
  'Lente · editor-en-jefe': 'editor-en-jefe',
  'Lente · jefe-client-success': 'jefe-client-success',
