const _meta = {};
// FIX 2026-08-09 (VF8 · exec 87625) · el lector buscaba `_meta` y no desenvolvia la forma-objeto.
// DATO de la corrida: las lentes emiten el estampado en `_field_meta` (el nombre que declaro CC#1)
// Y ADEMAS pueden mandar el campo como { valor, fuente, confianza }. El editor uso la forma-objeto
// (personalidad/tagline/mensajes) y el de cliente la forma plana: LAS DOS son validas y el esquema
// las acepta. Sin desenvolver, el borrador se quedaba con "[object Object]" (15 ch) en 3 campos y
// con TODAS las fuentes vacias, aunque las lentes las habian citado bien. Se acepta todo:
//   (1) campo = { valor, fuente, confianza }   (2) _field_meta[campo]   (3) _meta[campo] (alias)
const _nuevo = (lens, key, lensName, vacio) => {
  const st = lens.structured || {};
  let raw = st[key];
  let m = {};
  if (raw && typeof raw === "object" && !Array.isArray(raw) && ("valor" in raw)) { m = raw; raw = raw.valor; }
  const top = (st._field_meta && typeof st._field_meta === "object" && st._field_meta[key])
           || (st._meta && typeof st._meta === "object" && st._meta[key]) || {};
  if (!m.fuente && !Number.isFinite(Number(m.confianza))) m = top;
  else if (!m.fuente && top.fuente) m = Object.assign({}, top, m);
  const valor = (raw === undefined || raw === null) ? vacio : raw;
  const vacioReal = Array.isArray(valor) ? valor.length === 0 : !String(valor || "").trim();
  const c = Number(m.confianza);
  _meta[key] = { estado: vacioReal ? "ausente" : "provisional", provisional: true, gateado: false,
    fuente: typeof m.fuente === "string" ? m.fuente.slice(0, 200) : "",
    confianza: Number.isFinite(c) ? Math.max(0, Math.min(1, c)) : null,
    lente: lensName };
  return valor;
};
// P5c · que un TRUNCADO no se lea como MALA CALIDAD. Si la lente no emitio structured, el
