const structured_ok = { "brand-strategist": !!strat.structured, "editor-en-jefe": !!editor.structured, "jefe-client-success": !!cs.structured };


// UNION DE LAS 3 LENTES (2026-09-02 · CC#3) · dedup sin distinguir mayusculas,
// respetando el orden de llegada (editor primero, porque el campo es suyo).
// NUNCA quita: el resultado siempre contiene todo lo que el editor traia.
// Verificado contra exec 118856 (GoEuropeAdventure).
const _listaUnion = (key) => {
  const vistos = new Set(); const out = [];
  for (const l of [editor, strat, cs]) {
    const arr = (l.structured && l.structured[key]) || [];
    if (!Array.isArray(arr)) continue;
    for (const raw of arr) {
