  _lazo,
  _icp_chars,
  // 2026-08-07 (CC#2) · el margen contra TOPE_TASK se MIDE, no se asume: los 6999 del
  // diseno estan medidos con competitors:[] y en el tiro real suben. Que viva en el dato.
  _judge_task_chars: judgeTask.length,
  _icp_recortado,
  _materia_chars,        // E110 · cuánto de la materia del cliente vio el juez
  _materia_recortada,    // E110 · si la materia cedió (nunca silencioso)
  _omega_sin_espacio,
  _campos_cortados,     // campos que NO entraron al prompt · nunca se puntuan
  _campo_truncado,      // campo GATEADO cuyo valor hubo que recortar (patologico)
  _task_recortado,      // el guard de ultimo recurso mordio (no deberia)
  _evidencia_chars: evidencia.length,
  judge_step_name: 'bb-faithfulness-judge-c' + fidelityCycle,
  client_id: clientId,
  brand_book_draft: draft,
  _grounding_refs: grounding,
  cycle,
  _fidelity_cycle: fidelityCycle,
  threshold: THRESHOLD,
} }];

// Brand Book · Faithfulness judge · SCORING · paso 5 · ESTO decide canon (no votos).
// FIX 2026-07-01 · la llamada run-sdk se movió a un nodo HTTP previo ([BB] Judge · run-sdk)
// porque el fetch del Code node NO llegaba al runner en n8n (scores 0). Este nodo SOLO
// lee la respuesta del HTTP node (body.fidelity_scores) y computa la fidelidad.
//
// Input · $json = respuesta de [BB] Judge · run-sdk (body con fidelity_scores).
// Datos del draft/ciclo · via referencia a [BB] Judge prep.
// Output: { fidelity: { pass, threshold, scores, low_fields }, brand_book_draft, cycle }

const THRESHOLD = 0.85;
const MAX_FIDELITY_CYCLES = 2;   // pasadas de juez · cap=1 ⇒ 2 pasadas (CC#2 F2.1 · antes 1 mentía en `exhausted`)
// Todos los campos se PUNTÚAN + registran (transparencia · dashboards).
const SCORED_FIELDS = [
  'positioning', 'icp_summary', 'voice_description', 'customer_angle', 'retention_notes',
];
// FIX 2026-07-01 (consejero · Opción 1) · el GATE solo exige groundedness en los campos
// FÁCTICOS (positioning + icp_summary · verificables contra la evidencia de discovery).
// voice/customer_angle/retention_notes son DERIVACIONES CREATIVAS de marca (voz, ángulo,
// retención) · no hechos que se puedan "grounded" contra competidores/ICP · se puntúan
// pero NO bloquean el canon. El gate frena hechos inventados, no decisiones de marca.
const GATED_FIELDS = ['positioning', 'icp_summary'];

const prep = $('[BB] Judge prep').first().json;
const draft = prep.brand_book_draft || {};
const cycle = Number(prep.cycle) || 1;
const fidelityCycle = Number(prep._fidelity_cycle) || 1;

// La respuesta del nodo HTTP · el run-sdk surface los scores en body.fidelity_scores.scores.
const body = ($json && ($json.body || $json)) || {};
let scores = {};
if (body.fidelity_scores && body.fidelity_scores.scores) {
  scores = body.fidelity_scores.scores;
} else {
  // Fallback defensivo · parsear texto si el tool no fue capturado.
  const text = typeof body.response === 'string' ? body.response : JSON.stringify(body);
  const m = text.match(/\{[\s\S]*\}/);
  if (m) { try { scores = (JSON.parse(m[0]).scores) || {}; } catch (e) {} }
}

// 2026-08-07 (B.7) · el juez a veces emite `scores` como STRING pseudo-JSON con centinelas
// `<UNKNOWN>` en los campos que no puntua (quirk documentado · sonda P2 ·
// src/lib/jefatura/fidelity-grader.ts:94-136 `normalizeFidelityScores`). Indexar el string da
// undefined en TODOS los campos => con el piso viejo, cimiento legitimo REPROBADO y corrida
// pagada quemada. Se porta la extraccion tolerante de la plataforma.
// CONSERVADORA · NUNCA fabrica: lo no-numerico se OMITE => queda AUSENTE (que es justo lo que
// B sabe tratar) · jamas falso-verde.
// NOTA · SCORED_FIELDS de este nodo debe permanecer == FIDELITY_SCORE_FIELDS de
// fidelity-grader.ts (misma lista, mismo orden). Si una se toca, la otra tambien.
function normalizarScores(raw) {
  let obj = null;
  if (raw && typeof raw === 'object' && !Array.isArray(raw)) obj = raw;
  else if (typeof raw === 'string') {
    try { const p = JSON.parse(raw); if (p && typeof p === 'object' && !Array.isArray(p)) obj = p; } catch (e) {}
    if (!obj) {
      obj = {};
      for (const f of SCORED_FIELDS) {
        const m = raw.match(new RegExp('"' + f + '"\\s*:\\s*"?(-?\\d+(?:\\.\\d+)?)"?'));
        if (m) obj[f] = m[1];
      }
    }
  }
  if (!obj) return {};
  const out = {};
  for (const k of Object.keys(obj)) {
    const v = obj[k];
    // CC#2 · '' / null / [] / booleanos coaccionan a numero FINITO (0, 0, 0, 0/1) y FABRICARIAN
    // un score. Solo se aceptan numeros reales y strings numericos: el resto se OMITE => AUSENTE.
    if (typeof v === 'number') { if (Number.isFinite(v)) out[k] = v; continue; }
    if (typeof v === 'string' && v.trim() !== '') { const n = Number(v); if (Number.isFinite(n)) out[k] = n; }
  }
  return out;
}
scores = normalizarScores(scores);

// 2026-08-07 (B · ausente != cero) · un campo que el juez NO puntuo no es un campo reprobado:
// es un juez que no contesto. El piso a 0 disfrazaba una falla de EMISION de mala CALIDAD,
// disparaba una correccion incapaz de arreglar nada (no hay defecto) y podia reprobar un
// manual bueno. Precedente: 76543 emitio 3 de 5 campos.
// DEUDA GEMELA · src/lib/jefatura/fidelity-grader.ts:77-80 (`clamp01`, usado en L184-185) tiene
// EXACTAMENTE este bug. Hoy el flujo corre por ESTE nodo, asi que no bloquea; pero desde este
// cambio las dos versiones DIVERGEN (null honesto aca · 0 reprobado alla). Si el gate se mueve
// a la plataforma, este arreglo hay que portarlo o el defecto re-entra por la puerta de al lado.
// 2026-08-11 · un campo que NO ENTRO al prompt no es un campo malo: es un campo NO EVALUADO.
// En 90184 el juez devolvio 0 para customer_angle y retention_notes porque el tool le exige 5
// notas y esos dos no estaban en los CAMPOS. Ese 0 se registraba como si fuera una calificacion.
// Ahora [BB] Judge prep declara `_campos_cortados` y aca se FUERZA a no-evaluado, aunque el
// juez haya inventado un numero.
const _no_evaluados = Array.isArray(prep._campos_cortados) ? prep._campos_cortados : [];
const norm = {};
const ausentes = [];
for (const f of SCORED_FIELDS) {
  if (_no_evaluados.indexOf(f) !== -1) { ausentes.push(f); norm[f] = null; continue; }
  const raw = scores[f];
  const v = Number(raw);
  if (raw === undefined || raw === null || raw === '' || !Number.isFinite(v)) { ausentes.push(f); norm[f] = null; }
  else norm[f] = Math.max(0, Math.min(1, v));
}
const gated_ausentes = GATED_FIELDS.filter((f) => ausentes.indexOf(f) !== -1);
// red de seguridad · un gateado NUNCA deberia quedar fuera del prompt (entran primero por
// diseno). Si pasara, el gate no puede aprobar: no leyo lo que tenia que calificar.
const judge_incomplete = gated_ausentes.length > 0;
// BAJO solo aplica a los gateados que el juez SI puntuo.
const lowFields = GATED_FIELDS.filter((f) => norm[f] !== null && norm[f] < THRESHOLD);
// ADR-020 §7.6 · progreso monótono · una re-síntesis que NO sube la fidelidad → STOP + mejor versión.
// try/catch OBLIGATORIO (CC#2 F1): en la 1ª pasada '[BB] Lazo A prep' NO se ejecutó y referenciarlo
// LANZA · el || no salva (Number(undefined)=NaN ⇒ falsy ⇒ evalúa el 2º operando ⇒ lanza).
// Es el idioma que [BBA] Exit ya usa con el trigger.
// media SOLO sobre los gateados que el juez puntuo (antes los null sumaban como 0).
const gatedConScore = GATED_FIELDS.filter((f) => norm[f] !== null);
const gated_mean = gatedConScore.length ? gatedConScore.reduce((a, f) => a + norm[f], 0) / gatedConScore.length : 0;
let prev_best = Number($json.best_gated_mean) || 0;
let prev_draft = null;
try {
  const lp = $('[BB] Lazo A prep').first().json || {};
  prev_best = prev_best || Number(lp.best_gated_mean) || 0;
  prev_draft = lp.best_draft || null;
} catch (e) { /* 1ª pasada · el nodo del reintento todavía no corrió · piso 0 */ }
const improved = gated_mean > prev_best;
const pass = !judge_incomplete && lowFields.length === 0;

const no_progress = !pass && fidelityCycle > 1 && !improved;
// no contaminar la mejor version con una corrida en la que el juez no contesto.
const best_gated_mean_out = judge_incomplete ? prev_best : Math.max(gated_mean, prev_best);
const best_draft_out = (!judge_incomplete && improved) ? draft : (prev_draft || draft);
return [{
  json: {
    judge_incomplete,   // raiz · lo lee [BB] IF · ciclos agotados
    no_progress,
    best_gated_mean: best_gated_mean_out,
    best_draft: best_draft_out,
    gated_mean,
    fidelity: {
      pass,
      threshold: THRESHOLD,
      scores: norm,
      gated_fields: GATED_FIELDS, // solo éstos deciden el pase (Opción 1)
      low_fields: lowFields, // campos GATEADOS bajo umbral (los que bloquean)
      _lazo: (prep._lazo || null),   // F.b · pasa de largo · NO entra en ningun calculo
      judge_incomplete,      // el juez no puntuo algun campo GATEADO
      ausentes,              // todos los no puntuados (transparencia)
      no_evaluados: _no_evaluados,   // los que NO llegaron al prompt · distinto de "el juez no contesto"
      campo_truncado: (prep._campo_truncado || null),
      gated_ausentes,        // los que bloquean el pase
      cycle,
      fidelity_cycle: fidelityCycle,
      max_cycles: MAX_FIDELITY_CYCLES,
      // exhausted sobre el contador independiente · hard-cap real ≤3 aunque el judge falle.
      exhausted: !pass && fidelityCycle >= MAX_FIDELITY_CYCLES,
    },
    brand_book_draft: draft,
    cycle,
    _fidelity_cycle: fidelityCycle,
  },
}];

// CANDADO · LISTA BLANCA (C1 · Consejero 16-ago). Prohibir UN valor dejaba pasar undefined,
// vacio, o un tercer valor futuro. Se exige lo PERMITIDO. Y el try/catch no es decorativo:
// si alguien borra o renombra la Guardia, el $() lanza, _proc queda null, y null !== "padre"
// ⇒ BLOQUEA. Falla cerrado tambien contra C3 (el candado cuelga de un nombre de nodo).
let _proc = null;
try { _proc = $("[BB] Guardia de procedencia").first().json._procedencia; } catch (e) { _proc = null; }
if (_proc !== "padre") {
  throw new Error("CIMIENTO_PROMOCION_SIN_PADRE · procedencia=\"" + String(_proc) + "\" · solo promueve a canon una corrida invocada por el proceso padre. Diagnostico y ejecucion manual corren enteros pero NO escriben canon.");
}

// Brand Book · Promote prep · arma el body para el POST /brand-book.
// FIX 2026-07-01 · el nodo Promote era un Code node con fetch() · pero `fetch` NO existe
// en los Code nodes de n8n ("fetch is not defined") → no persistía. El POST se movió a un
// nodo HTTP Request (mismo patrón que el judge). Este nodo solo prepara el body.
//
// Corre SOLO en el branch PASS del IF de fidelidad (ya gateado) · igual guardamos el
// invariante 5 (nunca persistir sin PASS) por defensa.
const fidelity = ($json && $json.fidelity) || {};
const draft = ($json && $json.brand_book_draft) || {};
// P3 (endurecido 2026-07-30) · la fuente VALIDADA manda · el borrador del modelo NUNCA
// controla la dirección de escritura. Antes era al revés (draft primero).
const clientId = $('Validate Deal Data').first().json.client_id || draft.client_id;

const promote_body = {
  // HOOK DE HONESTIDAD (Emilio 2026-07-30 · dentro de brand_book · top-level lo descarta el endpoint):
  // el registro dice QUÉ se calificó de verdad. voz/ángulo/retención NO están gateados.
  brand_book: Object.assign({}, draft, {
    gated_fields_only: true,
    // FASE 1 p2 (H-A) · TRES baldes. Sin el 3ro, un campo SIN SEÑAL entraria como
    // "provisional" (que implica redactado) y el canon mentiria por omision. "ausente"
    // es ademas la lista de campos a pedirle a Emilio/cliente en la Fase 3.
    campos_gateados: ['positioning', 'icp_summary'],
    campos_provisionales: Object.keys(draft._field_meta || {}).filter((k) => (draft._field_meta[k] || {}).estado === "provisional"),
    campos_ausentes: Object.keys(draft._field_meta || {}).filter((k) => (draft._field_meta[k] || {}).estado === "ausente"),
    lentes_ok: (draft._build || {}).structured_ok || null,
    provisional: !!$('Validate Deal Data').first().json._sin_web,
  }),
  source: 'onboarding_collaborative_build',
  // CANON por fidelidad · NO por firma humana ni voto Camino III.
  fidelity_passed: !!fidelity.pass,
  // 2026-08-28 (pieza e · §144 Emilio) · este nodo ya no corre sólo en la rama
  // aprobada: el tope agotado también publica. El manual SALE SIEMPRE · el que no
  // alcanzó la vara sale MARCADO. Antes se retenía en silencio para una revisión
  // humana que nadie dispara: 0 manuales en 2 de 2 corridas del lazo.
  gate_outcome: fidelity.pass ? 'paso_la_vara' : 'salio_al_tope',
  gate_nota: fidelity.pass ? null : 'salió al tope, no alcanzó la vara',
  fidelity_scores: fidelity.scores,
  fidelity_threshold: fidelity.threshold,
  // firmar 'faithfulness_check' un manual que NO pasó la vara sería una mentira
  // en el registro · la firma dice quién lo dejó pasar, y al tope no lo dejó pasar
  // nadie: se agotaron las vueltas.
  approved_by: (fidelity.pass ? 'faithfulness_check' : 'cap_agotado'),
  // Date.now() está OK en Code nodes n8n (no es un workflow script del harness).
  approved_at: new Date().toISOString(),
};

return [{ json: {
  promote_body,
  client_id: clientId,
  // 2026-08-28 (e) · los DOS casos persisten · lo que cambia es la marca, no si sale.
  should_persist: true,
  gate_outcome: fidelity.pass ? 'paso_la_vara' : 'salio_al_tope',
  fidelity,
} }];

// Contrato de retorno al parent (CC#3 F2.2 · gate único = grade-cimiento en el parent).
// Track = PRODUCTOR: corre lentes→Consolidador→Judge y DEVUELVE scores+draft · NO decide/persiste.
// Retorna en TODAS las salidas (PASS y ciclos-agotados) · sin dead-end (cond.3).
// 2026-08-01 · CC#3 §2 · FALLA-FALSO. Con el ciclo, [BB] Faithfulness judge corre DOS veces
// (pasada 1 + pasada 2 tras la corrección) y este nodo corre UNA sola ⇒
// `$('[BB] Faithfulness judge').first()` puede resolver al runIndex 0 = LA PASADA 1 ⇒
// reportaría track_pass:false JUSTO CUANDO la corrección funcionó, con el manual ya escrito.
// Es el espejo del "listo falso": un FALLA-FALSO.
//
// Se prefiere la fuente DIRECTA del camino recorrido, que no depende de alinear runIndex:
//   · agotado → $json ES la salida del juez de la pasada 2 (viene por IF ciclos agotados out#0)
//   · PASS    → $('[BB] Promote prep') · corre UNA sola vez y emite `fidelity`
// El juez por referencia queda como ÚLTIMO recurso, no como fuente principal.
let src = null; let _return_source = 'ninguno';
if ($json && $json.fidelity) { src = $json; _return_source = 'json_directo'; }
if (!src) { try { const pp = $('[BB] Promote prep').first().json;
  if (pp && pp.fidelity) { src = pp; _return_source = 'promote_prep'; } } catch (e) {} }
if (!src) { try { src = $('[BB] Faithfulness judge').first().json; _return_source = 'juez_referencia'; }
  catch (e) { src = {}; _return_source = 'vacio'; } }
const fj = src;
const fid = fj.fidelity || {};
const draft = fj.brand_book_draft || (fj.promote_body && fj.promote_body.brand_book) || {};

// E99 (CC#3 2026-09-18) · este nodo DEBE ser el ÚLTIMO del cimiento: el motor devuelve al padre la
// salida del último nodo que corre. En la segunda bolita (141335) corría ANTES que «[BB] Manual → Drive (PDF)»
// y el padre recibió {"message":"Workflow was started"} ⇒ «cimiento no promovido» FALSO (canon 2176f143 escrito).
// El PDF ahora va antes y su acuse se anexa aquí · NO decide nada · si el nodo del PDF no corrió, se dice.
let _pdf = { solicitado: false, acuse: null };
try {
  const _a = $('[BB] Manual → Drive (PDF)').first().json || {};
  _pdf = { solicitado: _a.message === 'Workflow was started' || _a.ok === true, acuse: _a };
} catch (e) { _pdf = { solicitado: false, acuse: null, nota: 'el nodo del PDF no corrió antes que este' }; }
return [{ json: {
  fidelity_scores: fid.scores || {},
  brand_book_draft: fj.best_draft || draft,   // §7.6 · se devuelve la MEJOR versión registrada
  client_id: draft.client_id || fj.client_id || null,
  track_pass: !!fid.pass,          // ¿alcanzó la vara? · sigue siendo el dato honesto
  // 2026-08-28 (e) · «alcanzó la vara» y «se publicó» dejaron de ser lo mismo. El
  // padre necesita el segundo · si mirara el primero, un manual publicado al tope
  // no promovería el cimiento y la segunda fase nunca correría.
  track_published: !!(fj.promote_body || fid.pass || fid.exhausted),
  track_marked: !fid.pass,         // salió, pero no alcanzó · Emilio ve la marca
  track_exhausted: !!fid.exhausted,
  fidelity_cycle: Number(fj._fidelity_cycle || fid.fidelity_cycle || 1),
  // 2026-08-07 (B.4) · sin esto la distincion ausente/reprobado muere en la frontera y el padre
  // imprime ciclos_agotados=false sin explicar nada. En el carril del CIMIENTO no hay rechazo ni
  // bandeja humana: cap agotado => falla honesta + RETENCION (artefacto esencial · §16).
  // 2026-08-08 (F.b) · "el manual no alcanzo" y "la maquinaria no funciono" son OPUESTOS y
  // hasta hoy imprimian el mismo mensaje. El ciclo esteril gana sobre ciclos_agotados.
  track_reason: fid.judge_incomplete ? 'juez_incompleto'
              : (fid.pass ? 'pass'
              : ((fid._lazo && fid._lazo.esteril) ? 'ciclo_esteril:' + fid._lazo.esteril
              : (fid.exhausted ? 'ciclos_agotados' : 'fidelidad_baja'))),
  lazo_a: (fid._lazo || null),
  judge_incomplete: !!fid.judge_incomplete,
  _return_source,        // observabilidad · de qué fuente salió el veredicto (chequeo #6 del humo)
  pdf_manual: _pdf,   // E99 · acuse del PDF (informativo)
  _cimiento_return: true
} }];

// [BB] Lazo A prep · code · SIN LLM · prepara la invocación del ciclo de corrección.
// Hace 4 cosas, las 4 necesarias:
//  (1) completa _grounding_refs — el juez NO lo emite y el guard P0 del Lazo A salta sin él
//  (2) INCREMENTA _fidelity_cycle (+1) — el Consolidador ya no está en este camino:
//      sin este +1 el lazo NO TERMINA. El contador vive ACÁ, nunca dentro del sub-proceso.
//  (3) pasa low_fields/scores para que el revisor sepa QUÉ falló (arreglo 8.a)
//  (4) arrastra la mejor versión registrada (§7.6 progreso monótono)
const j = $json;
const fid = j.fidelity || {};
const draft = j.brand_book_draft || {};
let grounding = {};
try { grounding = $('[BB] Judge prep').first().json._grounding_refs || {}; } catch (e) { grounding = {}; }

// piso · nunca invocar la corrección sin artefacto (dispararía el guard P0 y volvería {})
if (!draft || Object.keys(draft).length === 0) {
  throw new Error('LAZO_A_SIN_BORRADOR · no se invoca la corrección sin artefacto');
}
// CC#2 F4 · simétrico · el guard P0 del Lazo A salta si el borrador O la evidencia vienen
// vacíos ⇒ Merge se queda sin ítems ⇒ Exit tampoco corre ⇒ el fail-closed no puede atrapar.
// Mejor fallar ruidoso ANTES de gastar que devolver nada en silencio después de 4 llamadas.
if (!grounding || Object.keys(grounding).length === 0) {
  throw new Error('LAZO_A_SIN_EVIDENCIA · no se invoca la corrección sin evidencia · el revisor diagnosticaría a ciegas');
}

return [{ json: {
  brand_book_draft: draft,
  _grounding_refs: grounding,
  client_id: draft.client_id || $('Validate Deal Data').first().json.client_id,
  cycle: Number(j.cycle) || 1,
  _fidelity_cycle: (Number(j._fidelity_cycle) || 0) + 1,
  low_fields: fid.low_fields || [],
  scores: fid.scores || {},
  best_draft: j.best_draft || draft,
  best_gated_mean: Number(j.best_gated_mean) || 0,
} }];

// RED TRIPLE contra el 500 de lente (CC#1 2026-08-10 · exec 87625).
// El 500 de plataforma mata la RESPUESTA pero el agente YA terminó y YA se cobró
// ($0,7581 en 87625) · sin red, `positioning` e `icp_summary` salen VACÍOS y se
// anula el eje del gate mientras la corrida sigue gastando.
// RED 1 · la sección DURABLE de la base (agent_invocations.metadata.brand_section).
const LENTES = [
  ['brand-strategist',    'Lente · brand-strategist',    'bb-lens-brand-strategist'],
  ['editor-en-jefe',      'Lente · editor-en-jefe',      'bb-lens-editor-en-jefe'],
  ['jefe-client-success', 'Lente · jefe-client-success', 'bb-lens-jefe-client-success'],
];
const seccionDirecta = (nodo) => {
  try { const j = $(nodo).first().json; const b = (j && j.body) || j; return (b && b.brand_section) || null; }
  catch (e) { return null; }
};
let filas = [];
try {
  const r = $('[BB] Rescate · leer invocaciones').first().json;
  filas = Array.isArray(r) ? r : (Array.isArray(r && r.body) ? r.body : []);
} catch (e) { filas = []; }
const seccionDeLaBase = (slug) => {
  for (const f of filas) {
    if (f && f.agent_name === slug && f.metadata && f.metadata.brand_section) return f.metadata.brand_section;
  }
  return null;
};
const secciones = {}, origen = {}, faltan = [];
for (const [slug, nodo, step] of LENTES) {
  let s = seccionDirecta(nodo), o = 'http';
  if (!s) { s = seccionDeLaBase(slug); o = s ? 'rescate_base' : null; }
  if (s) { secciones[slug] = s; origen[slug] = o; } else { faltan.push({ slug, nodo, step }); }
}
for (const k of Object.keys(origen)) {
  if (origen[k] === 'rescate_base') console.warn('[rescate] RED 1 · ' + k + ' recuperada de la base (la respuesta HTTP se perdió)');
}
const cid = $('Validate Deal Data').first().json.client_id;
let tasks = {};
try { tasks = $('[BB] Fan-out prep').first().json.tasks || {}; } catch (e) { tasks = {}; }
if (!faltan.length) return [{ json: { secciones, origen, _faltan: [], client_id: cid } }];
console.warn('[rescate] RED 2 · faltan tras la base: ' + faltan.map((f) => f.slug).join(', ') + ' → reintento 1 vez');
return faltan.map((f) => ({ json: {
